import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_none_counts_as_not_converted():
    events = [{"converted": True}, {"converted": None}, {"converted": False}]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([{"converted": None}]) == 0.0


def test_conversion_rate_empty():
    rate = conversion_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    rate = pooled_conversion_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 8, 7), ([], 0, 0), ([], 4, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_converted_values_and_field_whitespace():
    assert parse_session_log([" a , 2 , 1 \n", " b , -3 , 0 ", " c , 4 , \t"]) == [
        {"id": "a", "day": 2, "converted": True},
        {"id": "b", "day": -3, "converted": False},
        {"id": "c", "day": 4, "converted": None},
    ]


def test_parse_session_log_skips_blank_whitespace_and_comments():
    lines = ["", "\n", " \t\n", "# comment", " \t# comment,not,a,record",
             "x#1,3,0", "", " # trailing comment"]
    assert parse_session_log(lines) == [{"id": "x#1", "day": 3, "converted": False}]
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["x", "x,2", "x,2,1,extra", "x,no,1", "x,2.5,0", "x,,1"])
def test_parse_session_log_errors_include_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", " # comment", "valid,1,1", " \t", bad_line])


def test_dedupe_sessions_duplicate_ids_keep_last_record():
    events = [
        {"id": "b", "day": 8, "converted": True},
        {"id": "a", "day": 4, "converted": False},
        {"id": "b", "day": 1, "converted": False},
        {"id": "c", "day": 0, "converted": True},
        {"id": "a", "day": 1, "converted": None},
    ]
    assert dedupe_sessions(events) == [events[3], events[4], events[2]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_and_missing_days():
    events = [
        {"day": 4, "converted": True},
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 3, "converted": False},
        {"day": 1, "converted": True},
        {"day": 2, "converted": None},
        {"day": 5, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []


def test_daily_conversion_counts_empty_events():
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]
    assert daily_conversion_counts([], 1, 0) == []


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (4, 2), (10, 2)])
def test_campaign_summary_uses_calendar_days_and_pooled_rate(days, recent):
    groups = {
        "small": [{"id": "a", "day": 1, "converted": True}],
        "large": [
            {"id": "b", "day": 3, "converted": True},
            {"id": "c", "day": 4, "converted": None},
        ],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]),
                                         (10, ["best", "a", "z", "none"])])
def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [{"converted": True}, {"converted": False}],
        "empty": [],
        "a": [{"converted": True}, {"converted": None}],
        "none": [{"converted": False}],
        "best": [{"converted": True}],
    }
    assert top_converting_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_converting_groups_no_sessions(groups):
    assert top_converting_groups(groups, 5) == []


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    groups = {
        "z": [{"converted": False}],
        "b": [{"converted": True}, {"converted": None}],
        "a": [],
    }
    result = conversion_rate_by_group(groups)
    assert result == {"a": None, "b": 0.5, "z": 0.0}
    assert list(result) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, -2, 0], 0), ([1, 2, 3], 3),
     ([1, 0, 1, 1, 0, 1], 2), ([1, 1, -1, 1], 2), ([0, 1, 2, 3], 3)],
)
def test_longest_conversion_streak(counts, expected):
